import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"乘法器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/multiply/index.md","filePath":"v0.1.0-alpha/modules/multiply/index.md"}'),r={name:"v0.1.0-alpha/modules/multiply/index.md"};function n(l,t,i,c,h,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="乘法器" tabindex="-1">乘法器 <a class="header-anchor" href="#乘法器" aria-label="Permalink to &quot;乘法器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>multiply</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>把各输入流对应位置的数值相乘。两路正弦相乘可观察和频与差频，是理解混频和乘法调制的基础；向量输入则逐分量相乘。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>信号源 1.out → 乘法器.in1</code>，<code>信号源 2.out → 乘法器.in2</code>。将两个源与乘法结果分别绑定到观察工具，比较相乘前后的频率成分。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in1</code>（输入 1）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输入</td><td><code>in2</code>（输入 2）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（输出）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>输入必须具有相同元素类型、向量长度和实际采样率。增加输入路数表示再乘一项，不是增加求和项；任意一路为零会使相应位置的乘积为零。</p><p>混频前要考虑输出频率是否超过采样率的一半。即使输入频率各自合法，它们的和频仍可能折叠，不能把折叠结果当成原来的高频。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>输入路数<br><code>num_inputs</code></td><td><code>2</code></td><td>范围 1 至 1024；当前画布支持 1–1024 路。修改后须重新准备，缩减前请先解除相关连线和工具绑定。</td><td>重新准备</td></tr><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr><tr><td>元素类型<br><code>element_type</code></td><td><code>numeric_f64</code></td><td>实数 float32 (<code>numeric_f64</code>)；有符号 int16 (<code>int16</code>)；有符号 int32 (<code>int32</code>)</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>输入数量和数据形状属于运行结构，调整后停止并重新准备。当前任务继续使用已准备的接线，不能用草稿上的新端口推断运行输出。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="实数信号、分支运算与三种选频滤波" tabindex="-1">实数信号、分支运算与三种选频滤波 <a class="header-anchor" href="#实数信号、分支运算与三种选频滤波" aria-label="Permalink to &quot;实数信号、分支运算与三种选频滤波&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/real-processing.cnsproj" download>下载 real-processing.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>实数信号、分支运算与三种选频滤波</p><ul><li>64 Hz 与 768 Hz 混合信号分支进入低通、高通、带通；比较增益、相乘、8 点延时与两抽头 FIR。</li></ul><p>在实数处理示例中，两路正弦频率为 64 Hz 和 768 Hz。观察乘法器频谱，预期出现 704 Hz 与 832 Hz 分量；其相位和正负号由两路正弦的乘积关系决定。这些输出是本机计算结果。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>乘积幅度比输入小？</strong> 两路幅度相乘后还要考虑三角恒等式中的系数，不能直接期待两个幅度相加。</p><p><strong>想做固定比例缩放？</strong> 使用增益器更直接，无须增加一条常量输入流。</p>',26)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
